      "to": "Authenticated State"
    },
    {
      "from": "Authenticated State",
      "event": "SELECT/EXAMINE",
      "action": "Enter selected state",
      "to": "Selected State"
    }
  ]
}

{
  "states": [
    "authenticated",
    "selected"
  ],
  "transitions": [
    {
      "from": "authenticated",
      "event": "SELECT command succeeds",
      "action": "OK - select completed",
      "to": "selected"
    },
    {
      "from": "authenticated",
      "event": "SELECT command fails (no such mailbox, can't access)",
      "action": "NO - select failure",
      "to": "authenticated"
    },
    {
      "from": "selected",
      "event": "SELECT command on another mailbox succeeds",
      "action": "OK - select completed (automatically deselects previous)",
      "to": "selected"
    },
    {
      "from": "selected",
      "event": "SELECT command fails",
      "action": "NO - select failure",
      "to": "authenticated"
    }
  ]
}

